  (5397, 'the Western Wall', '嘆きの壁 Wailing Wall とも。（エルサレムにある、ユダヤ教の聖地。エルサレム旧市街の西側の城壁の一部の呼称。ユダヤ王ヘロデの時代に改築され、紀元70年にローマ軍によって破壊されたエルサレム神殿唯一の遺構。ユダヤ人の聖地とされ、中世以来、ユダヤ人はこの壁に額を押し当て、聖なる都の滅亡と神殿の荒廃を嘆き、その回復と復興を祈ってきた。）'),
  (5398, 'Dome of the Rock', '岩のドーム、イスラム教の聖地。アラビア語でクッバ・アッサフラと呼ばれ，エルサレムのアクサー・モスクを含む聖域内に建つ，現存するなかでは最古のイスラム建築。ウマイヤ朝のカリフ，アブドゥル・マリクが 687～691年に建立。サフラ (聖なる岩) をおおう中央ドームの周囲には，八角形回廊が2重にめぐらされ，幾何学的である。サフラはイスラム以前からアブラハムの伝説と結びつき神聖視されており，またムハンマドが昇天し，天界をめぐるために旅立った場所ともいわれる。'),
