  (8758, 'Larry the cat', 'ラリー(英語：Larry)はダウニング街10番地にある英首相官邸にいる猫で、首相官邸ネズミ捕獲長である。ラリーは茶色と白の雄のトラ猫で、2007年1月に生まれたといわれている。テリーザ・メイが首相になった2016年7月までには、ラリーは外務省に所属している、彼よりもずっと若い猫のパーマストンという地元の他のネズミ捕りとの関わりの中で「危険」という評判が広まった'),
  (8759, 'Dowing Street', 'ダウニング街10番地（ダウニングがいじゅうばんち、英語: 10 Downing Street）は、イギリスの首相が居住する官邸の所在地であり、官邸またはイギリス首相の代名詞として用いられる。イギリスではナンバー10 (Number 10) と呼ばれることが多い。'),
