  (10033, 'Sierra Nevada Mountains', 'シエラネヴァダ山脈。ヨセミテ国立公園がある。大陸横断鉄道建設の最大の難所だった。東西から進め、敷設した土地の周辺をあたえるという競争法案は、そもそも西側に大いに不利だったと言える。工事は進まないし、土地の価値は薄い。その最難関でうまみのないところに投入されたのが、アヘン/アロー戦争を逃れた中国人移民等だった。'),
