  (10057, 'Roe versus Wade', 'ロー対ウェイド事件(ローたいウェイドじけん、Roe v. Wade, 410 U.S. 113 (1973))は、「妊娠を継続するか否かに関する女性の決定はプライバシー権に含まれる」として、アメリカ合衆国憲法修正第14条が女性の堕胎の権利を保障していると初めて判示し、人工妊娠中絶を規制するアメリカ国内法の大部分を違憲無効とした、1973年のアメリカ合衆国最高裁判所の判決'),
