  (10196, 'LGBTQ', 'lesbian, gay, bisexual, transgender and queerの略。queerは本来、性的マイノリティーに対する差別語だが、従来の枠組みに当てはまらない多様な性的嗜好を持つ人が、自身を肯定的に捉える表現として用いる。また、Qはquestioningを表すこともあり、自分の性的嗜好を明確に決めていない人を指す'),
